from unittest.mock import Mock
from fetcher import fetch

# Mock implementation for testing
class MockClient: 
    def __init__(self, return_value=None):
        self.return_value = return_value

    def get(self, url, timeout=None):
        if timeout is not None and timeout != 30:
            raise ValueError("Timeout should be 30 in the tested implementation")
        return self.return_value

# Test case 1: Successful fetch
def test_successful_fetch():
    mock_client = MockClient(return_value={"data": "test data"})
    url = "http://test.com/api"
    result = fetch(mock_client, url)
    assert result == {"data": "test data"}

# Test case 2: Propagation of exceptions
class ConnectionError(Exception): pass

def test_exception_propagation():
    mock_client = MockClient(return_value=ConnectionError("network issue"))
    url = "http://failing.com/api"
    try:
        fetch(mock_client, url)
        assert False, "Expected ConnectionError but none was raised"
    except ConnectionError as e:
        assert str(e) == "network issue"

